CREATE DATABASE IF NOT EXISTS barangay_service_hub CHARACTER SET utf8mb4; USE barangay_service_hub;
SET FOREIGN_KEY_CHECKS=0; DROP TABLE IF EXISTS certificates,request_documents,requests,announcements,services,users; SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(30),address VARCHAR(255),role ENUM('resident','admin') NOT NULL DEFAULT 'resident',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE services(id INT AUTO_INCREMENT PRIMARY KEY,service_name VARCHAR(120) NOT NULL,description TEXT,requirements TEXT,processing_days INT DEFAULT 1,fee DECIMAL(10,2) DEFAULT 0,icon VARCHAR(30) DEFAULT 'file',status ENUM('active','inactive') DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE requests(id INT AUTO_INCREMENT PRIMARY KEY,reference_number VARCHAR(30) NOT NULL UNIQUE,user_id INT NOT NULL,service_id INT NOT NULL,purpose VARCHAR(255) NOT NULL,notes TEXT,status ENUM('Pending','In Process','Approved','For Payment','Completed','Rejected') DEFAULT 'Pending',payment_status ENUM('Unpaid','Paid') DEFAULT 'Unpaid',submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),INDEX(status),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE RESTRICT);
CREATE TABLE request_documents(id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL,file_name VARCHAR(255),file_path VARCHAR(255),uploaded_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES requests(id) ON DELETE CASCADE);
CREATE TABLE certificates(id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL,certificate_type VARCHAR(120),certificate_number VARCHAR(40),issued_date DATE,released_date DATE,status VARCHAR(30),FOREIGN KEY(request_id) REFERENCES requests(id) ON DELETE CASCADE);
CREATE TABLE announcements(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,content TEXT,announcement_date DATE,status ENUM('published','draft') DEFAULT 'published',created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
